scripts.script:
-- Change The Spider Tv To Whatever Unit You Like It Will Appear In Your Inventory
local args = {
    [1] = "Spider Tv"
}

game:GetService("ReplicatedStorage"):WaitForChild("InteractItem"):InvokeServer(unpack(args))

getgenv().settings = {
    toggle = true,
    wait = 0.1
}

while settings.toggle do
    wait(settings.wait)
    local luck = {"Super Luck Potion", "Luck Potion"}
    for _, v in ipairs(luck) do
        local args = {
            [1] = "Equip",
            [2] = v,
            [3] = "Usable"
        }
        game:GetService("ReplicatedStorage").Events.InventoryEvent:FireServer(unpack(args))
    end
end
